        assert!(state.strings.iter().all(Option::is_none) && state.messages.is_empty() && state.targets.is_empty() && state.active_bytes.is_none());
        drop(state);
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.state.is_none()
    }
}

