impl ArtifactCodec {
    /// 🏗️ Monomorphizes three non-capturing bridge functions for `(P, Mutation)` — each a
    /// genuine zero-sized `fn` item, coercible to a bare `fn` pointer — and pairs them with `schema`/
    /// `P::EXTENSION`. One call site per document kind (`register_document_codec_for_app`).
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — VALUE goes into `ArtifactCodec::compile_dsl`
    /// (`fn` slot, unnameable if `async fn`); wraps its real async body in `Box::pin` per R1(ii).
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🚫️async: E4 fn-pointer erasure-table thunk — see `compile_dsl_impl`'s tag above.
    ///
    /// 🌀️ `schema_hash` is async; `Option::map`'s closure is sync (R10 shape 1), so it's
    /// written as an explicit match instead.
    /// 🪶️ Constructs a codec with a required, actual relational snapshot implementation.
    pub fn of<P, Mutation>(schema: impl Into<String>) -> Self
    where
        P: Clone + PartialEq + ToValue + FromValue + ArtifactDsl + ArtifactPack + ArtifactSqliteSnapshot + Send + Sync + 'static,
        Mutation: self::Mutation<P> + PartialEq + ToValue + FromValue + OpText + OpBinary + Send + Sync + 'static,
    {
        let mut codec = Self::bare::<P, Mutation>(schema);
        codec.snapshot_sqlite = Some(P::sqlite_codec());
        codec
    }

    /// 📦️ Constructs a native document codec from its owner's declared capabilities.
    pub fn bare<P, Mutation>(schema: impl Into<String>) -> Self
    where
        P: Clone + PartialEq + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
        Mutation: self::Mutation<P> + PartialEq + ToValue + FromValue + OpText + OpBinary + Send + Sync + 'static,
    {
        /// 🕰️`'static`, not `'a`. These items are coerced to `for<'a> fn(..) -> ..` pointers, so a
        /// `P: 'a` bound would have to hold for EVERY lifetime — which is `'static` by another name,
        /// and which the compiler cannot infer from the bound as written ("one type is more general
        /// than the other"). The enclosing `of<P, Mutation>` already requires `'static` of both, so
        /// saying it here costs nothing and lets the coercion succeed.
        fn compile_dsl_impl<'a, P, Mutation>(dsl: &'a str, ops: &'a str) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<(ArtifactPackFiles, String), VcsError>> + Send + 'a>>
        where
            P: Clone + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let parsed: ParsedDocumentText<P, Mutation> = parse_document_text(dsl, ops).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                let envelope = parsed.into_envelope();
                let pack_files = print_document_pack(&envelope).await;
                let dsl_mirror = envelope.vcs.initial_snapshot.print_dsl();
                envelope.retire_unadopted();
                Ok((pack_files?, dsl_mirror))
            })
        }

        /// 🕰️`'static`, not `'a`. These items are coerced to `for<'a> fn(..) -> ..` pointers, so a
        /// `P: 'a` bound would have to hold for EVERY lifetime — which is `'static` by another name,
        /// and which the compiler cannot infer from the bound as written ("one type is more general
        /// than the other"). The enclosing `of<P, Mutation>` already requires `'static` of both, so
        /// saying it here costs nothing and lets the coercion succeed.
        fn print_mirror_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8]) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<ArtifactTextFiles, VcsError>> + Send + 'a>>
        where
            P: Clone + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let parsed: ParsedDocumentText<P, Mutation> = parse_document_pack(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                let envelope = parsed.into_envelope();
                let mirror = print_document_text(&envelope).await;
                envelope.retire_unadopted();
                mirror
            })
        }

        /// 🎯️ `encode_ops_vec(&[])` is a NON-empty framed header, not a zero-length byte
        /// slice — the empty-batch fast path must key off the DECODED mutation count, or an
        /// empty gesture builds a store, hits `EmptyApply`, and (before TC5) aborted in Drop.
        ///
        /// 🛂️ The throwaway reduction store gets the framework's own bounded owner
        /// catalogue. `ArtifactStore::new` installs NONE, and an uninstalled store cannot
        /// retire: the close cursor below answers `artifact store has no owner-supplied
        /// bounded disposer` for the first nonempty batch through a LINKED Rust codec —
        /// the path stdio and gis take on a hub. The guest twin
        /// (`plugin_runtime::artifact_app_apply_ops`) installs the APP's own catalogue
        /// there, which this thunk has no app type to ask for; the framework catalogue is
        /// the exact equivalent for a store that lives only for one reduction (ticket
        /// 26/09/18 slices TC3e §7d, TC4 §2).
        ///
        /// 🗄️ Never `?` while `store` is live: `ArtifactStore`'s Drop asserts a terminal
        /// shallow shell, so an early return here aborts the process instead of reporting the
        /// fault. Capture every fallible step as a value, run the close cursor, forget the
        /// store, THEN propagate — the guest twin does the same (ticket 26/09/18 TC3e/TC5).
        fn apply_ops_binary_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8], ops_vec: &'a [u8]) -> ArtifactCodecApplyFuture<'a>
        where
            P: Clone + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: ToValue + FromValue + OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let mutations: Vec<Mutation> = if ops_vec.is_empty() {
                    Vec::new()
                } else {
                    let op_blobs = crate::os_spr::decode_ops_vec(ops_vec).map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let mut decoded = Vec::with_capacity(op_blobs.len());
                    for bytes in &op_blobs {
                        decoded.push(Mutation::decode_op(bytes).map_err(|error| VcsError::Deserialize(error.to_string()))?);
                    }
                    decoded
                };
                if mutations.is_empty() {
                    if pack.is_empty() && spr.is_empty() {
                        return Ok((Vec::new(), Vec::new(), String::new()));
                    }
                    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let envelope = parsed.into_envelope();
                    let printed = print_document_pack(&envelope).await;
                    envelope.retire_unadopted();
                    let files = printed?;
                    return Ok((files.pack, files.spr, files.ops));
                }
                let mut store = if pack.is_empty() && spr.is_empty() {
                    return Err(VcsError::Deserialize("apply_ops_binary: lane has no pack+spr baseline".into()));
                } else {
                    let parsed = parse_document_pack::<P, Mutation>(pack, spr).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
                    let mut envelope = parsed.into_envelope();
                    let (applied, redo) = match &envelope.cursor {
                        Some(cursor) => (cursor.applied_edit_ids.clone(), cursor.redo_edit_ids.clone()),
                        None => (envelope.vcs.edits.iter().map(|edit| edit.id.clone()).collect(), crate::os_vcs::HistoryPageStack::new()),
                    };
                    envelope.cursor = Some(ArtifactCursor::new(applied, redo, envelope.cursor.as_ref().and_then(|cursor| cursor.checkpoint_id.clone())));
                    let mut store = ArtifactStore::new(envelope).await?;
                    store.install_document_store_owners_exact(bounded_artifact_store_owners::<P, Mutation>());
                    store
                };
                let applied = store.dispatch_apply_exact(mutations, None).await;
                let printed = match &applied {
                    Ok(_) => print_document_pack(&store.envelope).await,
                    Err(_) => Err(VcsError::ValidationFailed("artifact codec apply skipped print after a failed reduction".into())),
                };
                let closed = close_codec_reduction_store(store);
                applied?;
                closed?;
                let files = printed?;
                Ok((files.pack, files.spr, files.ops))
            })
        }

        fn replay_envelopes_impl<'a, P, Mutation>(pack: &'a [u8], spr: &'a [u8], envelopes: &'a [u8]) -> ArtifactCodecApplyFuture<'a>
        where
            P: Clone + ToValue + FromValue + ArtifactDsl + ArtifactPack + Send + Sync + 'static,
            Mutation: Clone + ToValue + FromValue + OpText + OpBinary + self::Mutation<P> + Send + Sync + 'static,
        {
            Box::pin(async move {
                let files = replay_envelopes_onto_pair::<P, Mutation>(pack, spr, envelopes, bounded_artifact_store_owners::<P, Mutation>).await?;
                Ok((files.pack, files.spr, files.ops))
            })
        }

        fn edit_text_from_envelope_impl<'a, P, Mutation>(envelope: &'a crate::os_spr::MutationEnvelope) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<String, VcsError>> + 'a>>
        where
            Mutation: OpText + OpBinary,
        {
            Box::pin(async move {
                let edit = edit_from_operation_envelope::<Mutation>(envelope).await?;
                print_edit_lines(&edit).await
            })
        }


        Self {
            schema: schema.into(),
            extension: P::EXTENSION,
            snapshot_sqlite: P::sqlite_snapshot_codec(),
            pack_schema_hash: match P::record_spec() {
                Some(spec) => crate::os_pack::schema_hash(&spec),
                None => [0u8; 32],
            },
            compile_dsl: compile_dsl_impl::<P, Mutation>,
            print_mirror: print_mirror_impl::<P, Mutation>,
            edit_text_from_envelope: edit_text_from_envelope_impl::<P, Mutation>,
            apply_ops_binary: apply_ops_binary_impl::<P, Mutation>,
            replay_envelopes: replay_envelopes_impl::<P, Mutation>,
        }
    }
}

static DOCUMENT_CODEC_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, ArtifactCodec>>> = std::sync::OnceLock::new();

fn document_codec_registry() -> &'static std::sync::RwLock<BTreeMap<String, ArtifactCodec>> {
    DOCUMENT_CODEC_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
}

/// ⚠️ A document schema already has a codec owner. The established codec is never replaced.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DocumentCodecRegistryConflict {
    pub schema: String,
}

/// ⚠️ Document-codec registration cannot replace an owner or use an unavailable registry.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum DocumentCodecRegistryError {
    Conflict(DocumentCodecRegistryConflict),
    Unavailable,
}

impl std::fmt::Display for DocumentCodecRegistryError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Conflict(error) => write!(formatter, "document codec registration conflicts for schema {}", error.schema),
            Self::Unavailable => formatter.write_str("document codec registry unavailable"),
        }
    }
}

impl std::error::Error for DocumentCodecRegistryError {}

fn same_document_codec(left: &ArtifactCodec, right: &ArtifactCodec) -> bool {
    left.schema == right.schema
        && left.extension == right.extension
        && match (left.snapshot_sqlite.as_ref(), right.snapshot_sqlite.as_ref()) {
            (Some(left), Some(right)) => left.identical_to(right),
            (None, None) => true,
            _ => false,
        }
        && left.pack_schema_hash == right.pack_schema_hash
        && std::ptr::fn_addr_eq(left.compile_dsl, right.compile_dsl)
        && std::ptr::fn_addr_eq(left.print_mirror, right.print_mirror)
        && std::ptr::fn_addr_eq(left.edit_text_from_envelope, right.edit_text_from_envelope)
        && std::ptr::fn_addr_eq(left.apply_ops_binary, right.apply_ops_binary)
        && std::ptr::fn_addr_eq(left.replay_envelopes, right.replay_envelopes)
}

fn validate_document_codecs(registry: &BTreeMap<String, ArtifactCodec>, codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let mut proposed: BTreeMap<&str, &ArtifactCodec> = BTreeMap::new();
    for codec in codecs {
        match proposed.get(codec.schema.as_str()) {
            Some(existing) if same_document_codec(existing, codec) => {}
            Some(_) => return Err(DocumentCodecRegistryError::Conflict(DocumentCodecRegistryConflict { schema: codec.schema.clone() })),
            None => {
                proposed.insert(codec.schema.as_str(), codec);
            }
        }
    }
    for (schema, codec) in proposed {
        match registry.get(schema) {
            Some(existing) if same_document_codec(existing, codec) => {}
            Some(_) => return Err(DocumentCodecRegistryError::Conflict(DocumentCodecRegistryConflict { schema: schema.to_string() })),
            None => {}
        }
    }
    Ok(())
}

/// 🔬️ Verifies document codecs against all established schemas without mutating the registry.
#[must_use]
pub async fn preflight_document_codecs(codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    preflight_document_codecs_in_assembly(&assembly, codecs)
}

/// 🔬️ Verifies document codecs while one artifact assembly owns the shared publication barrier.
#[must_use]
pub fn preflight_document_codecs_in_assembly(_assembly: &ArtifactAssemblyTransaction, codecs: &[ArtifactCodec]) -> Result<(), DocumentCodecRegistryError> {
    let registry = document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    validate_document_codecs(&registry, codecs)
}

/// 📝️ Registers one schema codec exactly once. Collisions fail deterministically before any
/// replacement can occur, so registration order never changes decoding behavior.
#[must_use]
pub fn register_document_codec(codec: ArtifactCodec) -> Result<(), DocumentCodecRegistryError> {
    register_document_codecs(vec![codec])
}

/// 📝️ Registers document codecs only when every descriptor and executable is conflict-free.
#[must_use]
pub fn register_document_codecs(codecs: Vec<ArtifactCodec>) -> Result<(), DocumentCodecRegistryError> {
    let assembly = begin_artifact_assembly().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    register_document_codecs_in_assembly(&assembly, codecs)
}

/// 📝️ Publishes preflighted document codecs while one artifact assembly owns the shared barrier.
#[must_use]
pub fn register_document_codecs_in_assembly(_assembly: &ArtifactAssemblyTransaction, codecs: Vec<ArtifactCodec>) -> Result<(), DocumentCodecRegistryError> {
    let mut registry = document_codec_registry().write().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    validate_document_codecs(&registry, &codecs)?;
    for codec in codecs {
        if !registry.contains_key(&codec.schema) {
            registry.insert(codec.schema.clone(), codec);
        }
    }
    Ok(())
}

/// 🔎️ Looks up the codec registered for `schema`, if any.
#[must_use]
pub async fn document_codec(schema: &str) -> Result<Option<ArtifactCodec>, DocumentCodecRegistryError> {
    let registry = document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    Ok(registry.get(schema).cloned())
}

/// 🧬️ A component codec answer still in flight. `Send` natively, where document owners run on
/// the shared worker pool; the browser's single isolate needs no `Send`.
#[cfg(not(target_arch = "wasm32"))]
pub type ComponentDocumentCodecFuture<'a, T> = std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, VcsError>> + Send + 'a>>;

#[cfg(target_arch = "wasm32")]
pub type ComponentDocumentCodecFuture<'a, T> = std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, VcsError>> + 'a>>;

/// 🧬️ One document kind's codec as the COMPONENT that owns the kind answers it — the
/// `world actor` `codec` interface (ticket 26/09/18 slice TC3b) — installed by the host that mounted
/// that component. A process that links no Rust codec for a kind identifies and validates its documents
/// through this, exactly as the hub's trusted catalog does for a package it links no codec for
/// (`🌎️hub/🗿️artifact-authority/🔏️trusted-catalog`'s `VerifiedNativeArtifactCodec`: its linked `codec`,
/// else its component `guest`).
pub trait ComponentDocumentCodec: Send + Sync {
    /// 🏷️ The document schema the component owns.
    fn schema(&self) -> &str;
    /// 🧬️ `codec.pack-schema-hash`: the kind's structural snapshot fingerprint.
    fn pack_schema_hash(&self) -> ComponentDocumentCodecFuture<'_, [u8; 32]>;
    /// 📥️ `codec.print-mirror`: the pair's text mirror, which is also its validation fence.
    fn print_mirror<'a>(&'a self, pack: &'a [u8], spr: &'a [u8]) -> ComponentDocumentCodecFuture<'a, ArtifactTextFiles>;
}

/// 🧭️ The one codec a document owner resolves for a schema: the Rust codec this binary links
/// when it links one, else the component codec installed for the mounted component that owns the kind.
#[derive(Clone)]
pub enum DocumentKindCodec {
    Linked(ArtifactCodec),
    Component(Arc<dyn ComponentDocumentCodec>),
}

impl DocumentKindCodec {
    /// 🧬️ The kind's structural snapshot fingerprint.
    pub async fn pack_schema_hash(&self) -> Result<[u8; 32], VcsError> {
        match self {
            Self::Linked(codec) => Ok(codec.pack_schema_hash),
            Self::Component(codec) => codec.pack_schema_hash().await,
        }
    }

    /// 📥️ The pair's text mirror; an `Err` means the pair is not a document of this kind.
    pub async fn print_mirror(&self, pack: &[u8], spr: &[u8]) -> Result<ArtifactTextFiles, VcsError> {
        match self {
            Self::Linked(codec) => (codec.print_mirror)(pack, spr).await,
            Self::Component(codec) => codec.print_mirror(pack, spr).await,
        }
    }
}

static COMPONENT_DOCUMENT_CODEC_REGISTRY: std::sync::OnceLock<std::sync::RwLock<BTreeMap<String, Arc<dyn ComponentDocumentCodec>>>> = std::sync::OnceLock::new();

fn component_document_codec_registry() -> &'static std::sync::RwLock<BTreeMap<String, Arc<dyn ComponentDocumentCodec>>> {
    COMPONENT_DOCUMENT_CODEC_REGISTRY.get_or_init(|| std::sync::RwLock::new(BTreeMap::new()))
}

/// 📝️ Installs a mounted component's codec for the schema it owns. A later mount of that kind's
/// owner replaces an earlier one: in this process the component a host mounted IS the kind's owner.
#[must_use]
pub fn register_component_document_codec(codec: Arc<dyn ComponentDocumentCodec>) -> Result<(), DocumentCodecRegistryError> {
    let mut registry = component_document_codec_registry().write().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    registry.insert(codec.schema().to_string(), codec);
    Ok(())
}

/// 🔎️ Resolves `schema` to the one codec a document owner uses — see [`DocumentKindCodec`].
#[must_use]
pub async fn document_kind_codec(schema: &str) -> Result<Option<DocumentKindCodec>, DocumentCodecRegistryError> {
    if let Some(codec) = document_codec(schema).await? {
        return Ok(Some(DocumentKindCodec::Linked(codec)));
    }
    let registry = component_document_codec_registry().read().map_err(|_| DocumentCodecRegistryError::Unavailable)?;
    Ok(registry.get(schema).cloned().map(DocumentKindCodec::Component))
}

/// 📜️ Reads the document schema id from an encoded `.spr` history log.
pub async fn lane_schema_from_spr(spr: &[u8]) -> Option<String> {
    if spr.is_empty() {
        return None;
    }
    crate::os_spr::decode_history(spr, &crate::os_spr::DecodeOptions::default()).await.ok().map(|log| log.schema).filter(|schema| !schema.is_empty())
}
